mapper.select:
SELECT MAX(created_at)
  FROM tb_member_otp
 WHERE member_id = #{memberId}
   AND purpose   = #{purpose}

SELECT COUNT(*)
  FROM tb_member_otp
 WHERE member_id  = #{memberId}
   AND purpose    = #{purpose}
   AND created_at >= #{since}

mapper.delete:
DELETE FROM tb_member_otp
 WHERE member_id  = #{memberId}
   AND purpose    = #{purpose}
   AND verified_at IS NULL

DELETE FROM tb_member_otp
 WHERE expires_at < #{threshold}
    OR verified_at IS NOT NULL
